import { subscribeFeed } from "./subscription.js";
import { presentBatch } from "./batch-presenter.js";

export function createFeedPanel({ history, paintRows, showCount }) {
  let current = null;
  const retire = () => {
    const previous = current;
    current = null;
    if (previous) previous.release();
  };
  return {
    show(feed, mode = "synchronous") {
      retire();
      const visit = { release: () => {} };
      current = visit;
      const release = subscribeFeed(feed, mode, frame => {
        // History has already run and may itself have navigated.
        if (current !== visit) return;
        presentBatch(frame, {
          paintRows,
          showCount: painted => {
            if (current === visit) showCount(painted);
          },
        });
      }, history);
      // Startup can synchronously navigate before returning its cleanup.
      visit.release = release;
      if (current !== visit) release();
    },
    close() {
      retire();
    },
  };
}

